//! The standard-name table (`std_names.rs`, generated by
//! `tools/gen-std-names.py`; w3-modules.md §2.12): its shape and a few names
//! every GCC declares. That it is fresh for the local g++ is checked by
//! b2c-codegen's `std_names` test, which runs the tool.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use b2c_ir::std_names::{NEWEST_GCC_MAJOR, STD_NAMES, STD_NAMES_GCC, StdNameKind, std_name};

#[test]
fn the_table_is_sorted_without_duplicates() {
    assert!(STD_NAMES.windows(2).all(|pair| pair[0].name < pair[1].name));
    assert!(STD_NAMES.iter().all(|entry| {
        let mut chars = entry.name.chars();
        chars.next().is_some_and(|c| c.is_ascii_alphabetic())
            && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
            && !entry.name.contains("__")
            && [17, 20, 23, 26].contains(&entry.since)
    }));
}

#[test]
fn it_names_the_gcc_it_came_from() {
    assert!(STD_NAMES_GCC.iter().all(|source| source.starts_with("GCC ")));
    let newest = STD_NAMES_GCC
        .iter()
        .filter_map(|source| source[4..].split('.').next()?.parse::<u32>().ok())
        .max();
    assert_eq!(newest, Some(NEWEST_GCC_MAJOR));
    const { assert!(NEWEST_GCC_MAJOR >= 11) };
}

#[test]
fn names_every_gcc_declares() {
    let kind = |name: &str| std_name(name).map(|entry| (entry.kind, entry.since));
    assert_eq!(kind("cout"), Some((StdNameKind::Object, 17)));
    assert_eq!(kind("string"), Some((StdNameKind::Type, 17)));
    assert_eq!(kind("vector"), Some((StdNameKind::ClassTemplate, 17)));
    assert_eq!(kind("list"), Some((StdNameKind::ClassTemplate, 17)));
    assert_eq!(kind("pair"), Some((StdNameKind::ClassTemplate, 17)));
    assert_eq!(kind("chrono"), Some((StdNameKind::Namespace, 17)));
    assert_eq!(kind("numbers"), Some((StdNameKind::Namespace, 20)));
    assert_eq!(kind("max"), Some((StdNameKind::Function, 17)));
    assert_eq!(kind("count"), Some((StdNameKind::Function, 17)));
    assert_eq!(kind("swap"), Some((StdNameKind::Function, 17)));
    // Names `std` does not declare.
    for name in ["area", "geo", "Box", "b2c", "std", "main", "__gnu_cxx"] {
        assert_eq!(std_name(name), None, "{name}");
    }
    assert!(StdNameKind::ClassTemplate.is_type_or_namespace());
    assert!(StdNameKind::Namespace.is_type_or_namespace());
    assert!(!StdNameKind::Function.is_type_or_namespace());
    assert!(!StdNameKind::Object.is_type_or_namespace());
}
